const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const langanoPoint = ee.Geometry.Point(38.742, 7.604); // Point in Lake Langano
  const abijataPoint = ee.Geometry.Point(38.603, 7.712); // Point in Lake Abijata
  const dateStart = '2022-03-29';
  const dateEnd = '2022-03-30';

  // 2. Data Acquisition & Filtering
  // Sentinel-2 Surface Reflectance is used for good color representation.
  const s2_collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(dateStart, dateEnd)
    .filter(ee.Filter.or(
        ee.Filter.bounds(langanoPoint),
        ee.Filter.bounds(abijataPoint)
    ));

  // Check if any images are available for the date.
  const imageCount = s2_collection.size().getInfo();
  if (imageCount === 0) {
    console.log('No Sentinel-2 images found for the specified date.');
    console.log('A'); // C1: Empty Collection
    return;
  }

  // Create a single mosaic from the available images (usually just one for a single day).
  const image = s2_collection.mosaic();

  // 3. Cloud Masking
  // A simple cloud mask using the Scene Classification Layer (SCL).
  const scl = image.select('SCL');
  // Keep pixels classified as water (6), vegetation (4), and soil (5).
  const mask = scl.eq(6).or(scl.eq(4)).or(scl.eq(5));
  const maskedImage = image.updateMask(mask);

  // 4. Processing & Calculation
  // We use the Red band (B4) as a proxy for "brownness" due to suspended sediment.
  // Higher reflectance in the red band indicates browner water.
  const band = 'B4';
  const scale = 30; // Scale for analysis

  // Function to get mean reflectance and pixel count for a point.
  const getStats = (point, lakeName) => {
    const region = point.buffer(100); // Buffer to get a representative area
    const stats = maskedImage.select(band).reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    });
    return ee.Dictionary(stats);
  };

  const langanoStats = getStats(langanoPoint, "Langano");
  const abijataStats = getStats(abijataPoint, "Abijata");

  // Retrieve the results. Use ee.Dictionary to handle potential nulls safely.
  const langanoDict = ee.Dictionary(langanoStats);
  const abijataDict = ee.Dictionary(abijataStats);

  const langanoMean = langanoDict.get(band);
  const langanoCount = langanoDict.get(band + '_count');
  const abijataMean = abijataDict.get(band);
  const abijataCount = abijataDict.get(band + '_count');

  // Run computations on the server before getting info.
  const results = ee.Dictionary({
      langanoMean: langanoMean,
      langanoCount: langanoCount,
      abijataMean: abijataMean,
      abijataCount: abijataCount
  }).getInfo();

  // 5. Validation & Final Answer
  if (results.langanoCount === 0 || results.abijataCount === 0) {
    console.log(`Lake Langano Valid Pixels: ${results.langanoCount}`);
    console.log(`Lake Abijata Valid Pixels: ${results.abijataCount}`);
    console.log('No valid (cloud-free) pixels found for one or both lakes.');
    console.log('C2');
    return;
  }

  if (results.langanoMean === null || results.abijataMean === null) {
      console.log('Calculation failed, result is null.');
      console.log('C3');
      return;
  }

  console.log(`Date: ${dateStart}`);
  console.log(`Image Count: ${imageCount}`);
  console.log(`Lake Langano Red Band Reflectance: ${results.langanoMean.toFixed(0)} (Pixels: ${results.langanoCount})`);
  console.log(`Lake Abijata Red Band Reflectance: ${results.abijataMean.toFixed(0)} (Pixels: ${results.abijataCount})`);

  if (results.langanoMean > results.abijataMean) {
    console.log('Conclusion: Lake Langano had higher red reflectance, indicating it was more brown.');
    console.log('A');
  } else {
    console.log('Conclusion: Lake Langano was not more brown than Lake Abijata.');
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during initialization or analysis:', e);
    console.log('D');
  }
}

initEE();
